1	import {
2	  Client,
3	  RippledError,
4	  Wallet,
5	  convertStringToHex,
6	  isValidClassicAddress,
7	  parseMPTokenIssuanceFlags,
8	  type Clawback,
9	  type LedgerEntry,
10	  type MPTokenAuthorize,
11	  type MPTokenIssuanceCreate,
12	  type MPTokenIssuanceSet,
13	  type Payment,
14	  type SubmittableTransaction,
15	  type TxResponse,
16	} from 'xrpl';
17	
18	/**
19	 * Bit flags on the per-holder MPToken ledger object (distinct from the
20	 * MPTokenIssuance flags, which xrpl.js already exposes via
21	 * parseMPTokenIssuanceFlags).
22	 */
23	const MPTOKEN_FLAG_LOCKED = 0x00000001;
24	const MPTOKEN_FLAG_AUTHORIZED = 0x00000002;
25	
26	export interface SubmittedTx {
27	  hash: string;
28	  resultCode: string;
29	}
30	
31	export interface CreateIssuanceParams {
32	  /** Decimal places used for display only; the ledger always stores integers. Defaults to 0. */
33	  assetScale?: number;
34	  /** Maximum number of base units that can ever be outstanding. Defaults to the protocol max (2^63-1). */
35	  maximumAmount?: string;
36	  /** Secondary-sale transfer fee in 1/100,000ths (0-50000 = 0%-50%). */
37	  transferFee?: number;
38	  /** Free-form metadata, conventionally JSON; stored on-ledger as hex. */
39	  metadata?: string;
40	  /** Whether holders may pay each other directly, not just the issuer. Defaults to true. */
41	  allowHolderToHolderTransfers?: boolean;
42	}
43	
44	export interface MptIssuanceSnapshot {
45	  issuanceId: string;
46	  issuer: string;
47	  outstandingAmount: string;
48	  maximumAmount?: string;
49	  assetScale?: number;
50	  transferFee?: number;
51	  requireAuth: boolean;
52	  canLock: boolean;
53	  canClawback: boolean;
54	  canTransfer: boolean;
55	  globallyLocked: boolean;
56	}
57	
58	export interface MptHolderSnapshot {
59	  account: string;
60	  issuanceId: string;
61	  balance: string;
62	  /** Issuer has approved this holder (relevant when the issuance requires auth). */
63	  authorized: boolean;
64	  /** Holder-specific freeze is in effect. */
65	  locked: boolean;
66	}
67	
68	export interface BanHolderResult {
69	  holder: string;
70	  /** Amount clawed back from the holder before revoking their authorization, "0" if they held nothing. */
71	  clawedBack: string;
72	  clawback?: SubmittedTx;
73	  revoke: SubmittedTx;
74	}
75	
76	function assertAddress(address: string, label: string): void {
77	  if (!isValidClassicAddress(address)) {
78	    throw new Error(`${label} is not a valid classic XRPL address: "${address}"`);
79	  }
80	}
81	
82	function assertPositiveIntegerString(value: string, label: string): void {
83	  if (!/^[1-9][0-9]*$/.test(value)) {
84	    throw new Error(`${label} must be a positive integer string in base units, got: "${value}"`);
85	  }
86	}
87	
88	function isEntryNotFoundError(error: unknown): boolean {
89	  if (!(error instanceof RippledError)) {
90	    return false;
91	  }
92	  const data = error.data as { error?: string } | undefined;
93	  return data?.error === 'entryNotFound';
94	}
95	
96	function extractResultCode(meta: TxResponse<SubmittableTransaction>['result']['meta']): string {
97	  if (meta == null) {
98	    throw new Error('Transaction response is missing metadata; cannot confirm outcome');
99	  }
100	  return typeof meta === 'string' ? meta : meta.TransactionResult;
101	}
102	
103	/**
104	 * Issuer-side control surface for a single Multi-Purpose Token issuance,
105	 * built for a regulated / stablecoin-style deployment:
106	 *
107	 *  - Allowlist: the issuance is created with tfMPTRequireAuth, so only
108	 *    holders the issuer explicitly authorizes can hold a balance.
109	 *  - Clawback: created with tfMPTCanClawback.
110	 *  - Per-holder and global freeze: created with tfMPTCanLock.
111	 *  - Bans: implemented as clawback-to-zero + revoking the holder's
112	 *    authorization, so a banned address can neither hold nor receive
113	 *    the token again.
114	 *
115	 * All state-changing methods submit a signed transaction and wait for
116	 * validated, tesSUCCESS confirmation before resolving; on any other
117	 * outcome they throw.
118	 */
119	export class MptIssuer {
120	  private readonly client: Client;
121	  private readonly wallet: Wallet;
122	  private mptIssuanceId: string | undefined;
123	
124	  constructor(client: Client, issuerWallet: Wallet, issuanceId?: string) {
125	    this.client = client;
126	    this.wallet = issuerWallet;
127	    this.mptIssuanceId = issuanceId;
128	  }
129	
130	  get issuerAddress(): string {
131	    return this.wallet.address;
132	  }
133	
134	  get issuanceId(): string {
135	    if (!this.mptIssuanceId) {
136	      throw new Error('No MPT issuance attached yet; call createIssuance() first or pass issuanceId to the constructor');
137	    }
138	    return this.mptIssuanceId;
139	  }
140	
141	  private async submit<T extends SubmittableTransaction>(
142	    tx: T,
143	  ): Promise<{ submitted: SubmittedTx; response: TxResponse<T> }> {
144	    const response = await this.client.submitAndWait<T>(tx, { wallet: this.wallet });
145	    if (!response.result.validated) {
146	      throw new Error(`${tx.TransactionType} was not validated: ${JSON.stringify(response.result)}`);
147	    }
148	    const resultCode = extractResultCode(response.result.meta);
149	    if (resultCode !== 'tesSUCCESS') {
150	      throw new Error(`${tx.TransactionType} failed with ${resultCode}: ${JSON.stringify(response.result)}`);
151	    }
152	    return { submitted: { hash: response.result.hash, resultCode }, response };
153	  }
154	
155	  /** Creates the MPT issuance with allowlist, clawback, and lock (freeze) capability enabled. */
156	  async createIssuance(params: CreateIssuanceParams = {}): Promise<{ issuanceId: string } & SubmittedTx> {
157	    const tx: MPTokenIssuanceCreate = {
158	      TransactionType: 'MPTokenIssuanceCreate',
159	      Account: this.wallet.address,
160	      Flags: {
161	        tfMPTRequireAuth: true,
162	        tfMPTCanLock: true,
163	        tfMPTCanClawback: true,
164	        tfMPTCanTransfer: params.allowHolderToHolderTransfers ?? true,
165	      },
166	      ...(params.assetScale !== undefined ? { AssetScale: params.assetScale } : {}),
167	      ...(params.maximumAmount !== undefined ? { MaximumAmount: params.maximumAmount } : {}),
168	      ...(params.transferFee !== undefined ? { TransferFee: params.transferFee } : {}),
169	      ...(params.metadata !== undefined ? { MPTokenMetadata: convertStringToHex(params.metadata) } : {}),
170	    };
171	
172	    const { submitted, response } = await this.submit(tx);
173	    const meta = response.result.meta;
174	    const issuanceId = meta == null || typeof meta === 'string' ? undefined : meta.mpt_issuance_id;
175	    if (!issuanceId) {
176	      throw new Error('MPTokenIssuanceCreate succeeded but returned no mpt_issuance_id in its metadata');
177	    }
178	    this.mptIssuanceId = issuanceId;
179	    return { issuanceId, ...submitted };
180	  }
181	
182	  /**
183	   * Allowlists a holder who has already opted in (submitted their own
184	   * MPTokenAuthorize). Required before that holder can send or receive
185	   * the token, since the issuance requires auth.
186	   */
187	  async approveHolder(holderAddress: string): Promise<SubmittedTx> {
188	    assertAddress(holderAddress, 'holderAddress');
189	    const tx: MPTokenAuthorize = {
190	      TransactionType: 'MPTokenAuthorize',
191	      Account: this.wallet.address,
192	      MPTokenIssuanceID: this.issuanceId,
193	      Holder: holderAddress,
194	    };
195	    return (await this.submit(tx)).submitted;
196	  }
197	
198	  /**
